<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class TarificationController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head'),403);}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$req=DB::table('load_requirements as q')->join('study_groups as g','g.id','=','q.study_group_id')->join('subjects as s','s.id','=','q.subject_id')->leftJoin('study_types as st','st.id','=','q.study_type_id')->where('q.academic_period_id',$p->id)->select('q.*','g.name group_name','s.name subject_name','st.name study_type_name')->get();foreach($req as $x){$x->assigned=DB::table('teaching_load_plans')->where(['academic_period_id'=>$p->id,'study_group_id'=>$x->study_group_id,'subject_id'=>$x->subject_id])->when($x->study_type_id,fn($q)=>$q->where('study_type_id',$x->study_type_id))->sum('hours_total');$x->balance=round($x->required_hours-$x->assigned,2);}$teachers=DB::table('teachers as t')->where('t.active',1)->select('t.*')->orderBy('t.last_name')->get();foreach($teachers as $x){$x->hours=DB::table('teaching_load_plans')->where(['academic_period_id'=>$p->id,'teacher_id'=>$x->id])->sum('hours_total');$x->weekly=DB::table('teaching_load_plans')->where(['academic_period_id'=>$p->id,'teacher_id'=>$x->id])->sum('hours_week');$x->rate=DB::table('teaching_load_plans')->where(['academic_period_id'=>$p->id,'teacher_id'=>$x->id])->sum('rate_fraction');}$vacant=DB::table('teaching_load_plans as l')->join('study_groups as g','g.id','=','l.study_group_id')->join('subjects as s','s.id','=','l.subject_id')->where(['l.academic_period_id'=>$p->id,'l.vacant'=>1])->select('l.*','g.name group_name','s.name subject_name')->get();return view('academic-office.tarification',compact('p','req','teachers','vacant'));}
 public function generate(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);DB::transaction(function()use($p){DB::table('load_requirements')->where('academic_period_id',$p->id)->where('source','work_program')->delete();$plans=DB::table('curriculum_plans')->where(['academic_period_id'=>$p->id,'approval_status'=>'approved'])->get();foreach($plans as $cp){$hours=DB::table('curriculum_topics')->where('curriculum_plan_id',$cp->id)->sum('planned_hours');DB::table('load_requirements')->updateOrInsert(['academic_period_id'=>$p->id,'study_group_id'=>$cp->study_group_id,'subject_id'=>$cp->subject_id,'study_type_id'=>null],['required_hours'=>$hours,'source'=>'work_program','created_at'=>now(),'updated_at'=>now()]);}});return back()->with('success','Потребность пересчитана по утверждённым рабочим программам.');}
 public function allocate(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['study_group_id'=>'required|exists:study_groups,id','subject_id'=>'required|exists:subjects,id','study_type_id'=>'required|exists:study_types,id','teacher_id'=>'nullable|exists:teachers,id','hours_total'=>'required|numeric|min:.1','hours_week'=>'nullable|numeric|min:0','subgroup'=>'nullable|string|max:100','rate_fraction'=>'nullable|numeric|min:0|max:10']);$source=(DB::table('teaching_load_plans')->where('academic_period_id',$p->id)->max('source_load_id')??0)+1;DB::table('teaching_load_plans')->insert($d+['academic_period_id'=>$p->id,'source_load_id'=>$source,'vacant'=>empty($d['teacher_id']),'status'=>'active','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Нагрузка распределена.');}
 public function print(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$rows=DB::table('teaching_load_plans as l')->leftJoin('teachers as t','t.id','=','l.teacher_id')->join('study_groups as g','g.id','=','l.study_group_id')->join('subjects as s','s.id','=','l.subject_id')->leftJoin('study_types as st','st.id','=','l.study_type_id')->where('l.academic_period_id',$p->id)->select('l.*','t.last_name','t.first_name','t.middle_name','g.name group_name','s.name subject_name','st.name study_type_name')->orderBy('t.last_name')->orderBy('g.name')->get();return view('academic-office.tarification-print',compact('p','rows'));}
}